package com.progressly.goal.api;
import com.progressly.goal.domain.Goal; import jakarta.validation.Valid; import java.util.*; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/goals") public class GoalController { private final GoalService service; public GoalController(GoalService service){this.service=service;} private UUID user(Authentication a){return UUID.fromString(a.getName());}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public GoalDtos.GoalResponse create(Authentication a,@Valid @RequestBody GoalDtos.GoalRequest r){return service.create(user(a),r);} @GetMapping public Page<GoalDtos.GoalResponse> list(Authentication a,Pageable p){return service.list(user(a),p);} @GetMapping("/{id}") public GoalDtos.GoalResponse get(Authentication a,@PathVariable UUID id){return service.get(user(a),id);} @PutMapping("/{id}") public GoalDtos.GoalResponse update(Authentication a,@PathVariable UUID id,@Valid @RequestBody GoalDtos.GoalRequest r){return service.update(user(a),id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(Authentication a,@PathVariable UUID id){service.delete(user(a),id);} @PostMapping("/{id}/progress") public GoalDtos.GoalResponse progress(Authentication a,@PathVariable UUID id,@Valid @RequestBody GoalDtos.ProgressRequest r){return service.progress(user(a),id,r);}
 @PostMapping("/{id}/milestones") @ResponseStatus(HttpStatus.CREATED) public GoalDtos.MilestoneResponse add(Authentication a,@PathVariable UUID id,@Valid @RequestBody GoalDtos.MilestoneRequest r){return service.addMilestone(user(a),id,r);} @GetMapping("/{id}/milestones") public List<GoalDtos.MilestoneResponse> milestones(Authentication a,@PathVariable UUID id){return service.milestones(user(a),id);} @PutMapping("/{id}/milestones/{milestoneId}") public GoalDtos.MilestoneResponse updateMilestone(Authentication a,@PathVariable UUID id,@PathVariable UUID milestoneId,@Valid @RequestBody GoalDtos.MilestoneRequest r){return service.updateMilestone(user(a),id,milestoneId,r);} @PatchMapping("/{id}/milestones/{milestoneId}/complete") public GoalDtos.MilestoneResponse complete(Authentication a,@PathVariable UUID id,@PathVariable UUID milestoneId,@RequestParam boolean value){return service.completeMilestone(user(a),id,milestoneId,value);} @DeleteMapping("/{id}/milestones/{milestoneId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteMilestone(Authentication a,@PathVariable UUID id,@PathVariable UUID milestoneId){service.deleteMilestone(user(a),id,milestoneId);}
}
